// cartographer:hook:guard — generated by Cartographer, do not edit.
// KB event: PreToolUse (matcher: "Edit|Write") → Pi: tool_call

import { spawnSync } from "node:child_process"

const HOOK_NAME = "guard"
const HOOK_EVENT = "PreToolUse"
const COMMAND = "$BASE/.pi/agent/cartographer-hooks/guard/notify.sh"
const MATCHER = "Edit|Write"

// Unanchored and case-insensitive: Pi's built-ins are lowercase, MCP tools are
// mcp__<server>__<tool>, the KB's matchers are Claude's. A pattern the JS engine
// rejects makes the hook inert.
function matches(toolName) {
  if (!MATCHER) return true
  try { return new RegExp(MATCHER, "i").test(String(toolName ?? "")) } catch { return false }
}

// Returns { status, stderr }, or null on a spawn error or a timeout.
function run(payload, cwd) {
  try {
    const r = spawnSync("sh", ["-c", COMMAND], { input: JSON.stringify(payload), encoding: "utf8", cwd: cwd || undefined, timeout: 60000 })
    if (r.error || r.status === null || r.status === undefined) return null
    return { status: r.status, stderr: String(r.stderr || "").trim() }
  } catch { return null }
}

export default function (pi) {
  pi.on("tool_call", async (event, ctx) => {
    try {
      if (!matches(event.toolName)) return
      const r = run({ hook_event_name: HOOK_EVENT, cwd: ctx?.cwd, tool_name: event.toolName, tool_input: event.input, tool_use_id: event.toolCallId }, ctx?.cwd)
      if (r && r.status === 2) return { block: true, reason: r.stderr || "blocked by hook " + HOOK_NAME }
    } catch {}
  })
}
